```python
class MinHeap:
    def __init__(self):
        # 使用列表存储堆，索引从 0 开始
        self.heap = []

    def _parent(self, i):
        return (i - 1) // 2

    def _left_child(self, i):
        return 2 * i + 1

    def _right_child(self, i):
        return 2 * i + 2

    def _swap(self, i, j):
        self.heap[i], self.heap[j] = self.heap[j], self.heap[i]

    def _heapify_up(self, i):
        """将索引 i 处的元素向上调整，维持最小堆性质"""
        while i > 0:
            parent = self._parent(i)
            if self.heap[i] < self.heap[parent]:
                self._swap(i, parent)
                i = parent
            else:
                break

    def _heapify_down(self, i):
        """将索引 i 处的元素向下调整，维持最小堆性质"""
        n = len(self.heap)
        while True:
            left = self._left_child(i)
            right = self._right_child(i)
            smallest = i

            if left < n and self.heap[left] < self.heap[smallest]:
                smallest = left
            if right < n and self.heap[right] < self.heap[smallest]:
                smallest = right

            if smallest != i:
                self._swap(i, smallest)
                i = smallest
            else:
                break

    def insert(self, value):
        """插入元素"""
        self.heap.append(value)
        self._heapify_up(len(self.heap) - 1)

    def extract_min(self):
        """提取并返回最小元素，若堆为空则抛出异常"""
        if not self.heap:
            raise IndexError("extract_min from empty heap")
        if len(self.heap) == 1:
            return self.heap.pop()

        min_val = self.heap[0]
        # 将最后一个元素移到根
        self.heap[0] = self.heap.pop()
        # 向下调整
        self._heapify_down(0)
        return min_val

    def peek_min(self):
        """查看最小元素但不删除"""
        if not self.heap:
            raise IndexError("peek_min from empty heap")
        return self.heap[0]

    def is_empty(self):
        return len(self.heap) == 0

    def size(self):
        return len(self.heap)


# 简单测试
if __name__ == "__main__":
    h = MinHeap()
    values = [5, 3, 8, 1, 9, 2]
    for v in values:
        h.insert(v)
        print("插入后堆:", h.heap)

    print("最小元素:", h.peek_min())

    while not h.is_empty():
        print("extract_min:", h.extract_min())
```

说明要点：
- 使用列表 `self.heap` 存储堆元素。
- `insert`：在末尾添加元素，然后调用 `_heapify_up` 向上调整。
- `extract_min`：取出根节点（最小值），用末尾元素替换根，再调用 `_heapify_down` 向下调整。
- 时间复杂度：
  - `insert`：O(log n)
  - `extract_min`：O(log n)
  - `peek_min`：O(1)

